import math
V=App.Vector
def cyl(r,h,p,axis=(0,0,1)):
    return Part.makeCylinder(r,h,V(*p),V(*axis))
def box(l,w,h,p):
    return Part.makeBox(l,w,h,V(*p))
def compound(parts):
    return Part.makeCompound(parts)
def ring(ro,ri,length,p,axis=(0,1,0)):
    return cyl(ro,length,p,axis).cut(cyl(ri,length,p,axis))
def rod(a,b,r):
    a=V(*a); b=V(*b); d=b-a
    return Part.makeCylinder(r,d.Length,a,d)
def polyprism(points,vector):
    vs=[V(*p) for p in points];vs.append(vs[0])
    return Part.Face(Part.makePolygon(vs)).extrude(V(*vector))
def rhs(a,b,width,height,t):
    ax,ay,az=a;bx,by,bz=b;dx=bx-ax;dy=by-ay;le=math.hypot(dx,dy);nx=-dy/le;ny=dx/le;ux=dx/le;uy=dy/le
    def prism(xa,ya,xb,yb,w,z,h):
        return polyprism([(xa+nx*w/2,ya+ny*w/2,z),(xb+nx*w/2,yb+ny*w/2,z),(xb-nx*w/2,yb-ny*w/2,z),(xa-nx*w/2,ya-ny*w/2,z)],(0,0,h))
    return prism(ax,ay,bx,by,width,az,height).cut(prism(ax-ux,ay-uy,bx+ux,by+uy,width-2*t,az+t,height-2*t))
def hexsolid(r,h,p,axis="z"):
    x,y,z=p
    pts=[(x+r*math.cos(k*math.pi/3),y+r*math.sin(k*math.pi/3),z) for k in range(6)] if axis=="z" else [(x+r*math.cos(k*math.pi/3),y,z+r*math.sin(k*math.pi/3)) for k in range(6)]
    return polyprism(pts,(0,0,h) if axis=="z" else (0,h,0))
shape=rhs((0,-1*(params["w"]/2-params["b"]/2),0),(params["l"],-1*(params["w"]/2-params["b"]/2),0),params["b"],params["h"],params["t"])
if shape.isNull() or not shape.isValid():
    raise ValueError("Geometria invalida: FR-LONG-I")

